<script setup lang="ts">
import { Palette as PaletteIcon, Save, ImagePlus, SlidersHorizontal, ArrowRight } from 'lucide-vue-next'
import { normalizePalette, paletteSchema, usedColorTokens, paletteEntries, resolveColor, prepareComponent, imageSlots, replaceImageSlot, assetUrl, type ImageSpec, type ComponentData, type Palette, type Resource, type Asset } from '@qinbian/shared'
import { fitImageAsset, assetIdFromUrl } from '~/utils/image-slots'
const props=defineProps<{data:ComponentData;themeSetId?:string}>(),emit=defineEmits<{update:[data:ComponentData]}>(),ctx=useQinbian()
const croppingField=ref(''),imageBusy=ref('')
const bindingRoot=ref<HTMLElement>()
defineExpose({focusField(id:string){const el=id?bindingRoot.value?.querySelector<HTMLInputElement|HTMLTextAreaElement>(`[data-field-id="${id}"] input,[data-field-id="${id}"] textarea`):undefined;el?.scrollIntoView({block:'center'});el?.focus();el?.select()}})
const cards=ref<Resource[]>([]),cardsOpen=ref(false),editing=ref(false),draft=ref<Palette>(normalizePalette(props.data.palette)),token=ref(''),imageField=ref('')
const palette=computed(()=>normalizePalette(props.data.palette,ctx.themes.value.find(t=>t.id===props.themeSetId)?.tokens))
const tokens=computed(()=>usedColorTokens(props.data.html||'')),entries=computed(()=>paletteEntries(palette.value))
const fields=computed(()=>props.data.fields||[])
function update(patch:Partial<ComponentData>){emit('update',prepareComponent({...props.data,...patch},palette.value))}
function beginEdit(){draft.value=structuredClone(toRaw(palette.value));editing.value=true}
function setValue(id:string,value:string|number){update({values:{...props.data.values,[id]:value}})}
function mappingLabel(t:string){const mapped=props.data.colorMappings?.[t]||t;return entries.value.find(e=>e.token===mapped)?.label||mapped}
function changeMapping(choice:{token?:string;value:string}){const mappings={...props.data.colorMappings};if(choice.token===token.value)delete mappings[token.value];else mappings[token.value]=choice.token||choice.value;update({colorMappings:mappings});token.value=''}
function applyPalette(p:Palette){if(!paletteSchema.safeParse(p).success){ctx.notify('每个颜色需有名称和有效色值，共 3–6 色',true);return}const mappings={...props.data.colorMappings};for(const t of tokens.value)if(!paletteEntries(p).some(e=>e.token===t))mappings[t]=resolveColor(t,palette.value,mappings);update({palette:p,colorMappings:mappings});cardsOpen.value=false;editing.value=false}
async function pickCard(){try{cards.value=await apiFetch<Resource[]>('/api/resources',{query:{kind:'palette'}});cardsOpen.value=true}catch(e){ctx.error(e)}}
async function saveCard(){try{await apiFetch('/api/resources',{method:'POST',body:{kind:'palette',themeSetId:'mine',name:palette.value.name||'我的配色',description:'从组件中收录的配色',category:'配色卡',tags:['配色'],data:{palette:palette.value}}});ctx.notify('配色卡已保存')}catch(e){ctx.error(e)}}
function fieldImage(id:string){return imageSlots(props.data.html||'').find(s=>s.fieldId===id)}
function applyImageAsset(id:string,a:Asset,spec:ImageSpec){const index=imageSlots(props.data.html||'').findIndex(s=>s.fieldId===id);update({html:index>=0?replaceImageSlot(props.data.html||'',index,assetUrl(a.id),a.name,spec):props.data.html,fields:fields.value.map(f=>f.id===id?{...f,image:spec}:f),values:{...props.data.values,[id]:assetUrl(a.id)}});croppingField.value=''}
function applyCroppedField(a:Asset,spec:ImageSpec){applyImageAsset(croppingField.value,a,spec)}
async function chooseImage(a:Asset){const id=imageField.value,spec=fieldImage(id)?.spec||fields.value.find(f=>f.id===id)?.image||{shape:'rect'};imageField.value='';imageBusy.value=id;try{const fitted=await fitImageAsset(a,spec);applyImageAsset(id,fitted,spec)}catch(e){ctx.error(e)}finally{imageBusy.value=''}}
</script>
<template><section ref="bindingRoot" class="component-bindings"><div class="bindings-heading"><h4><PaletteIcon :size="14"/>配色与映射</h4><button class="text-button" @click="beginEdit">调整配色</button></div><div class="binding-palette-strip"><i v-for="c in palette.colors" :key="c.id" :style="{background:c.regular}" :title="c.name"/></div><div class="bindings-actions"><button class="text-button" @click="pickCard">选用配色卡</button><button class="text-button" @click="saveCard"><Save :size="12"/>收为配色卡</button></div><div v-if="tokens.length" class="mapping-list"><button v-for="t in tokens" :key="t" @click="token=t"><span><i :style="{background:resolveColor(t,palette,data.colorMappings)}"/><span>{{entries.find(e=>e.token===t)?.label||t}}<code>{{t}}</code></span></span><span class="mapping-target">{{mappingLabel(t)}}<ArrowRight :size="11"/></span></button></div><p v-else class="small muted">当前元素使用自定义颜色。</p><div v-if="fields.length" class="data-field-list"><h4>可修改内容与数据</h4><label v-for="f in fields" :key="f.id" :data-field-id="f.id"><span>{{f.label}}<small>{{f.id}}</small></span><template v-if="f.type==='text'"><textarea :value="data.values?.[f.id]??f.default" rows="2" @input="setValue(f.id,($event.target as HTMLTextAreaElement).value)"/></template><template v-else-if="f.type==='number'"><input :value="data.values?.[f.id]??f.default" type="number" :min="f.min" :max="f.max" :step="f.step||'any'" @input="setValue(f.id,Number(($event.target as HTMLInputElement).value))"><small v-if="f.suffix">{{f.suffix}}</small></template><template v-else-if="f.type==='image'"><button class="btn" :disabled="imageBusy===f.id" @click="imageField=f.id"><ImagePlus :size="14"/>{{imageBusy===f.id?'正在适配图片…':fieldImage(f.id)?.src?'替换图片':'选择图片'}}</button><button v-if="assetIdFromUrl(fieldImage(f.id)?.src||'')" class="text-button" @click="croppingField=f.id">调整裁切</button></template><template v-else><output>由其他数值自动计算</output></template></label></div>
 <ColorPicker v-if="token" :title="'修改映射 '+token" :palette="palette" :mappings="data.colorMappings" @close="token=''" @choose="changeMapping"/>
 <UiModal v-if="editing" title="组件配色" subtitle="" @close="editing=false"><PaletteEditor v-model="draft" :used-tokens="tokens"/><div class="modal-actions"><button class="btn primary" @click="applyPalette(draft)">应用组件配色</button></div></UiModal>
 <UiModal v-if="cardsOpen" title="选择配色卡" subtitle="只应用于当前组件。" wide @close="cardsOpen=false"><div class="palette-picker-grid"><button v-for="card in cards" :key="card.id" @click="applyPalette(normalizePalette(card.data.palette))"><h3>{{card.name}}</h3><PaletteSwatches :palette="card.data.palette" compact/></button></div><p v-if="!cards.length" class="muted small">暂无配色卡。可在资源库的“配色卡”中创建。</p></UiModal>
 <ImageCropper v-if="croppingField" :asset-id="assetIdFromUrl(fieldImage(croppingField)?.src||'')" :spec="fieldImage(croppingField)?.spec" @close="croppingField=''" @apply="applyCroppedField"/>
 <AssetPicker v-if="imageField" @close="imageField=''" @select="chooseImage"/>
 </section></template>
